public class UserPoolRegionalConfigurationAttachmentFactory(string resourceName = null, Action<Humidifier.Cognito.UserPoolRegionalConfigurationAttachment> factoryAction = null) : ResourceFactory<Humidifier.Cognito.UserPoolRegionalConfigurationAttachment>(resourceName)
{

    internal InnerUserPoolRegionalConfigurationAttachmentEmailConfigurationFactory EmailConfigurationFactory { get; set; }

    internal InnerUserPoolRegionalConfigurationAttachmentSmsConfigurationFactory SmsConfigurationFactory { get; set; }

    internal InnerUserPoolRegionalConfigurationAttachmentLambdaConfigFactory LambdaConfigFactory { get; set; }

    protected override Humidifier.Cognito.UserPoolRegionalConfigurationAttachment Create()
    {
        var userPoolRegionalConfigurationAttachmentResult = CreateUserPoolRegionalConfigurationAttachment();
        factoryAction?.Invoke(userPoolRegionalConfigurationAttachmentResult);

        return userPoolRegionalConfigurationAttachmentResult;
    }

    private Humidifier.Cognito.UserPoolRegionalConfigurationAttachment CreateUserPoolRegionalConfigurationAttachment()
    {
        var userPoolRegionalConfigurationAttachmentResult = new Humidifier.Cognito.UserPoolRegionalConfigurationAttachment
        {
            GivenName = InputResourceName,
        };

        return userPoolRegionalConfigurationAttachmentResult;
    }
    public override void CreateChildren(Humidifier.Cognito.UserPoolRegionalConfigurationAttachment result)
    {
        base.CreateChildren(result);

        result.EmailConfiguration ??= EmailConfigurationFactory?.Build();
        result.SmsConfiguration ??= SmsConfigurationFactory?.Build();
        result.LambdaConfig ??= LambdaConfigFactory?.Build();
    }

} // End Of Class

